using System;
using System.CodeDom.Compiler;
using System.Collections.Generic;
using System.Linq;
using System.Reflection;
using ConventionMapper.Testing;

namespace ConventionMapper.Tests.TestingPackage
{
    /// <summary>ConventionMapper.Testing refuses mappers generated by another major or minor version of the generator.</summary>
    public class TestingVersionTests
    {
        // Mappers generated by this build (same version) are covered by every other Testing test.
        // Stand-ins for generated mapper classes: a generated method stamped with the generator's version, and WriteSets.
        public static class OldMapper
        {
            internal static readonly IReadOnlyDictionary<string, IReadOnlyList<string>> WriteSets =
                new Dictionary<string, IReadOnlyList<string>> { ["ToDto"] = new[] { "Id" } };

            [GeneratedCode("ConventionMapper.SourceGenerator", "1.2.0")]
            public static int ToDto(int id) => id;
        }

        public static class UnstampedMapper
        {
            internal static readonly IReadOnlyDictionary<string, IReadOnlyList<string>> WriteSets =
                new Dictionary<string, IReadOnlyList<string>> { ["ToDto"] = new[] { "Id" } };

            public static int ToDto(int id) => id;
        }

        [Fact]
        public void A_mapper_from_another_minor_version_fails_with_both_versions()
        {
            var error = Assert.Throws<MapperAssertException>(() => MapperAssert.WriteSetOf(typeof(OldMapper), "ToDto"));

            Assert.Contains("ConventionMapper.SourceGenerator 1.2.0", error.Message);
            Assert.Contains("ConventionMapper.Testing " + TestingVersion(), error.Message);
            Assert.Contains("same major and minor version", error.Message);
        }

        [Fact]
        public void Unstamped_mappers_are_accepted()
        {
            // A target framework without GeneratedCodeAttribute: nothing to compare.
            Assert.Equal(new[] { "Id" }, MapperAssert.WriteSetOf(typeof(UnstampedMapper), "ToDto"));
        }

        private static string TestingVersion()
        {
            var version = typeof(MapperAssert).Assembly.GetCustomAttribute<AssemblyInformationalVersionAttribute>()!.InformationalVersion;
            var plus = version.IndexOf('+');
            return plus >= 0 ? version.Substring(0, plus) : version;
        }
    }
}
